# Variant: Mostly Defect with conditional cooperation based on observed cooperation rate, recipient reputation, own history, and round number.

observed_actions = []  # global sliding window of observed actions (booleans: True=cooperate, False=defect)
MAX_WINDOW = 10

def evaluate(current_reputation, observation, my_history, round_num):
    # Extract action and update sliding window
    action = observation["action"]
    is_coop = (action == "cooperate")
    global observed_actions
    observed_actions.append(is_coop)
    if len(observed_actions) > MAX_WINDOW:
        observed_actions.pop(0)

    # Reputation update: symmetric but with a small extra sensitivity to extreme reputations
    if is_coop:
        if current_reputation < 0:
            return 0.8   # big positive for a sucker who cooperates
        else:
            return 0.3   # moderate positive
    else:  # defect
        if current_reputation > 0:
            return -0.8  # big negative for a trusted agent who defects
        else:
            return -0.3  # moderate negative

def decide(recipient_reputation, round_num, my_history):
    # Compute own recent cooperation rate from my_history (list of past decisions as bools)
    if len(my_history) == 0:
        own_coop_rate = 0.5
    else:
        own_coops = sum(1 for a in my_history if a)
        own_coop_rate = own_coops / len(my_history)

    # Compute observed cooperation rate from global window
    global observed_actions
    if len(observed_actions) == 0:
        obs_coop_rate = 0.5
    else:
        obs_coop_rate = sum(observed_actions) / len(observed_actions)

    # Endgame: always defect in the last third of the 15-round game
    if round_num > 10:
        return False

    # Condition to cooperate: high recipient reputation, recent observations show cooperation,
    # and own cooperation rate is not too high (avoid being exploited)
    if recipient_reputation > 0.3 and obs_coop_rate > 0.5 and own_coop_rate < 0.6:
        return True
    else:
        return False

