def evaluate(current_reputation, observation, my_history, round_num):
    # Update reputation using an exponential moving average.
    # Reward cooperation (+1) and punish defection (-1), blending with prior reputation.
    if observation['action'] == 'cooperate':
        new_rep = 0.9 * current_reputation + 0.1 * 1.0
    else:
        new_rep = 0.9 * current_reputation + 0.1 * (-1.0)
    return new_rep

def decide(recipient_reputation, round_num, my_history):
    # Compute our own past cooperation rate (indirect measure, not partner-specific).
    if my_history:
        own_coop_rate = sum(1 for m in my_history if m['action'] == 'cooperate') / len(my_history)
    else:
        own_coop_rate = 0.5  # neutral initial value

    # Adjust threshold based on our own behaviour:
    # - If we have cooperated a lot, we become more trusting (lower threshold).
    # - If we have defected a lot, we become more cautious (higher threshold).
    threshold = 0.5 + 0.2 * (0.5 - own_coop_rate)

    return recipient_reputation > threshold

def evaluate(current_reputation, observation, my_history, round_num):
    # Exponential moving average: weight recent action but smooth with current reputation
    # Returns value between -1 and 1
    new_rep = 0.7 * current_reputation + 0.3 * (1.0 if observation['action'] == 'cooperate' else -1.0)
    return max(-1.0, min(1.0, new_rep))

def decide(recipient_reputation, round_num, my_history):
    # Count own defections so far (first element of each history tuple)
    own_defections = sum(1 for coop, _ in my_history if not coop)
    # Defect unconditionally until 2 own defections (shorter initial phase)
    if own_defections < 2:
        return False
    # After the initial phase, cooperate with anyone who has non-negative reputation
    return recipient_reputation > 0.0

def evaluate(current_reputation, observation, my_history, round_num):
    # Modified update: stronger reaction to actions, lower memory decay.
    if observation['action'] == 'cooperate':
        new_rep = current_reputation * 0.7 + 0.2
    else:  # defect
        new_rep = current_reputation * 0.7 - 0.3
    return max(-1.0, min(1.0, new_rep))

def decide(recipient_reputation, round_num, my_history):
    # Threshold starts lower and decreases more slowly than original.
    # Also becomes more forgiving if I have been cooperative myself.
    threshold = 0.4 - round_num * 0.003
    if len(my_history) > 5:
        # Count how many times I cooperated (True) so far.
        coop_count = sum(1 for action in my_history if action)
        if coop_count >= len(my_history) * 0.5:
            threshold -= 0.1  # extra forgiveness
    return recipient_reputation > threshold
